import React, { useState, useMemo } from 'react';
import axios from 'axios';
import '../styles/CartPage.css';
import { API_URL_Cart_Page, API_URL_PAYMENT } from '../api';

const BASE_URL = process.env.REACT_APP_BASE_URL || 'https://polyglotacademy.am';
const IDRAM_ACCOUNT_ID = '100049302';
const PAYMENT_DESCRIPTION = 'Your purchase description';
const CUSTOMER_EMAIL = 'academy.polyglott@gmail.com';

function IdramPaymentForm({ amount, billNo }) {
    console.log('🟡 Idram Payment Form Values:', { amount, billNo });

    return (
        <form
            action="https://banking.idram.am/Payment/GetPayment"
            method="POST"
            id="idramPaymentForm"
        >
            <input type="hidden" name="EDP_LANGUAGE" value="EN" />
            <input type="hidden" name="EDP_REC_ACCOUNT" value={IDRAM_ACCOUNT_ID} />
            <input type="hidden" name="EDP_DESCRIPTION" value={PAYMENT_DESCRIPTION} />
            <input type="hidden" name="EDP_AMOUNT" value={amount} />
            <input type="hidden" name="EDP_BILL_NO" value={billNo} />
            <input type="hidden" name="EDP_EMAIL" value={CUSTOMER_EMAIL} />
            <input type="hidden" name="SUCCESS_URL" value={`${BASE_URL}/success`} />
            <input type="hidden" name="FAIL_URL" value={`${BASE_URL}/fail`} />
            <input type="hidden" name="RESULT_URL" value="https://main-api.academy-polyglot.site/result" />
        </form>
    );
}

function CartPage({ cart, updateQuantity, removeItem }) {
    const [customerInfo, setCustomerInfo] = useState({
        name: '',
        surname: '',
        phone: '',
    });
    const [modalOpen, setModalOpen] = useState(false);
    const [paymentStatus, setPaymentStatus] = useState({
        success: false,
        error: null,
    });
    const [orderId, setOrderId] = useState(null);
    const [loading, setLoading] = useState(false);

    const isFormValid = useMemo(() => {
        return (
            customerInfo.name.trim() &&
            customerInfo.surname.trim() &&
            customerInfo.phone.trim() &&
            cart.length > 0
        );
    }, [customerInfo, cart]);

    const totalAmount = useMemo(() => {
        return cart.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
    }, [cart]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCustomerInfo((prevInfo) => ({ ...prevInfo, [name]: value }));
    };

    const handlePayment = () => {
        setModalOpen(true);
    };

    const confirmPayment = async () => {
        setLoading(true);
        try {
            // Օրդերի տվյալներ ստեղծելու համար
            const orderData = {
                customer_name: customerInfo.name,
                customer_surname: customerInfo.surname,
                customer_phone: customerInfo.phone,
                cart_items: cart.map(item => ({
                    product_id: item.id,
                    quantity: item.quantity,
                    price: item.price,
                    selected_type: item.selectedType
                })),
                total_amount: parseFloat(totalAmount)
            };

            console.log('🟡 Order Data:', orderData);

            // Օրդեր ստեղծենք
            const orderResponse = await axios.post(API_URL_Cart_Page, orderData);
            const billNo = orderResponse.data.order_id;

            if (!billNo) {
                throw new Error('Failed to create order');
            }

            // Վճարման հայտ ուղարկենք
            const paymentResponse = await axios.post(API_URL_PAYMENT, {
                amount: totalAmount,
                billNo: billNo
            });

            if (!paymentResponse.data.success) {
                throw new Error('Payment processing failed');
            }

            // Կարճ պաուզա վիճակի թարմացման համար
            await new Promise((resolve) => setTimeout(resolve, 100));

            // Դնենք billNo-ն որպես orderId
            setOrderId(billNo);

            // Իրականացնենք վճարման ձևը
            const paymentForm = document.getElementById('idramPaymentForm');
            if (!paymentForm) {
                throw new Error('Payment form not found');
            }

            paymentForm.submit();

        } catch (error) {
            console.error('🔴 Payment Error:', error);
            setPaymentStatus({
                success: false,
                error: error.message || 'An error occurred during payment'
            });
        } finally {
            setLoading(false);
            setModalOpen(false);
        }
    };

    const cancelPayment = () => {
        setModalOpen(false);
    };

    return (
        <>
            <div className="cart-page">
                <h2>Your Cart</h2>
            </div>
            <div className="container">
                <div className="cart-page-container">
                    <div className="cart-table">
                        <table>
                            <thead>
                            <tr>
                                <th>Images</th>
                                <th>Product</th>
                                <th>Unit Price</th>
                                <th>Quantity</th>
                                <th>Total</th>
                                <th>Remove</th>
                            </tr>
                            </thead>
                            <tbody>
                            {cart.map((item) => (
                                <tr key={`${item.id}-${item.selectedType}`} className="cart-item">
                                    <td>
                                        <img src={item.image} alt={item.name} className="cart-item-image"/>
                                    </td>
                                    <td>{item.name}</td>
                                    <td>{item.price} AMD</td>
                                    <td>
                                        <div className="quantity-controls">
                                            <button
                                                onClick={() =>
                                                    updateQuantity(
                                                        item.id,
                                                        item.selectedType,
                                                        Math.max(item.quantity - 1, 1)
                                                    )
                                                }
                                            >
                                                -
                                            </button>
                                            <input
                                                type="number"
                                                value={item.quantity}
                                                min="1"
                                                onChange={(e) =>
                                                    updateQuantity(
                                                        item.id,
                                                        item.selectedType,
                                                        parseInt(e.target.value) || 1
                                                    )
                                                }
                                            />
                                            <button
                                                onClick={() =>
                                                    updateQuantity(item.id, item.selectedType, item.quantity + 1)
                                                }
                                            >
                                                +
                                            </button>
                                        </div>
                                    </td>
                                    <td>{(item.price * item.quantity).toFixed(2)} AMD</td>
                                    <td>
                                        <button
                                            onClick={() => removeItem(item.id, item.selectedType)}
                                            className="remove-button"
                                        >
                                            ×
                                        </button>
                                    </td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>

                    <div className="checkout-section">
                        <div className="customer-info">
                            <h3>Customer Information</h3>
                            <div className="input-group">
                                <label>Name</label>
                                <input
                                    type="text"
                                    name="name"
                                    placeholder="Name"
                                    value={customerInfo.name}
                                    onChange={handleInputChange}
                                />
                            </div>
                            <div className="input-group">
                                <label>Surname</label>
                                <input
                                    type="text"
                                    name="surname"
                                    placeholder="Surname"
                                    value={customerInfo.surname}
                                    onChange={handleInputChange}
                                />
                            </div>
                            <div className="input-group">
                                <label>Phone Number</label>
                                <input
                                    type="text"
                                    name="phone"
                                    placeholder="Phone Number"
                                    value={customerInfo.phone}
                                    onChange={handleInputChange}
                                />
                            </div>
                        </div>

                        <div className="cart-totals">
                            <h3>Cart Totals</h3>
                            <div className="total-row">
                                <span>Subtotal</span>
                                <span>{totalAmount} AMD</span>
                            </div>
                            <div className="total-row">
                                <span>Total</span>
                                <span>{totalAmount} AMD</span>
                            </div>
                            <button
                                className="proceed-to-checkout"
                                onClick={handlePayment}
                                disabled={!isFormValid || loading}
                            >
                                {loading ? 'Processing...' : 'Proceed To Checkout'}
                            </button>
                        </div>

                        {paymentStatus.error && (
                            <p className="error-message">{paymentStatus.error}</p>
                        )}
                    </div>
                </div>
            </div>

            {modalOpen && (
                <div className="modal-overlay">
                    <div className="modal-box">
                        <p>Please confirm your details.</p>
                        <div className="modal-buttons">
                            <button className="button" onClick={confirmPayment}>
                                Yes
                            </button>
                            <button className="button" onClick={cancelPayment}>
                                No
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <IdramPaymentForm amount={totalAmount} billNo={orderId}/>
        </>
    );
}

export default CartPage;
